import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.math.BigInteger

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val writer = BufferedWriter(OutputStreamWriter(System.out))

    var t = reader.readLine().toInt()
    while (t-- > 0) {
        val (n, k) = reader.readLine().split(" ").map { it.toLong() }
        val mod = 1000000007L
        val ans = BigInteger.valueOf(n).modPow(BigInteger.valueOf(k), BigInteger.valueOf(mod))
        writer.write(ans.toString())
        writer.newLine()
    }
    writer.flush()
}

import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.math.BigInteger
import kotlin.math.abs
import kotlin.math.log10
import kotlin.math.pow

/*
1
1 1
1 2
2 1
2 3
---
0
0
2 [0,1], [1,0]
X [0,7], [7,0],

*/

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val writer = BufferedWriter(OutputStreamWriter(System.out))

    var t = 1
    t = reader.readLine()!!.toInt()

    while (t-- > 0) {
        val (n, k) = reader.readLine()!!.split(" ").map { it.toLong() }

        val mod = 1000000007L
        val ans = BigInteger.valueOf(n).modPow(BigInteger.valueOf(k), BigInteger.valueOf(mod)).toLong()

        writer.write("$ans\n")
    }

    writer.flush()
}

fun reversed(s: String): String {
    val input = s.toCharArray()
    val li = input.size
    val ret = CharArray(li)
    for (i in input.indices) {
        ret[li - i - 1] = input[i]
    }
    return String(ret)
}

fun divCeil(num: Int, div: Int): Int {
    var quot = num / div
    if (num % div != 0) {
        quot++
    }
    return quot
}

fun min(vararg nums: Int): Int {
    var minimum = nums[0]
    for (num in nums) {
        if (num < minimum) {
            minimum = num
        }
    }
    return minimum
}

fun max(vararg nums: Int): Int {
    var maximum = nums[0]
    for (num in nums) {
        if (num > maximum) {
            maximum = num
        }
    }
    return maximum
}

fun abs(num: Int): Int {
    return if (num < 0) -num else num
}

fun isPrime(num: Int): Boolean {
    if (num == 2 || num == 3) {
        return true
    }

    if (num <= 1 || num % 2 == 0 || num % 3 == 0) {
        return false
    }

    var i = 5
    while (i * i <= num) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return false
        }
        i += 6
    }

    return true
}

fun gcd(a: Int, b: Int): Int {
    var a = a
    var b = b
    while (b != 0) {
        val temp = b
        b = a % b
        a = temp
    }
    return a
}

fun lcm(a: Int, b: Int): Int {
    return abs(a) / gcd(a, b) * abs(b)
}

fun digitAt(num: Int, pos: Int): Int {
    if (num == 0) {
        return 0
    }

    var num = num
    num = abs(num)

    val lenNum = log10(num.toDouble()).toInt() + 1
    if (pos < 0 || pos >= lenNum) {
        throw RuntimeException("Out of bound access for digit. Position passed $pos, number $num")
    }

    val rem = num % 10.0.pow(pos + 1).toInt()
    return rem / 10.0.pow(pos).toInt()
}

